var quiz_default = "export interface Question {\n  id: string;\n  group: string;\n  topic: string;\n  text: string;\n  answers: string[];\n  correct: number[];\n  explanation: string;\n  remember?: string;\n  image?: string;\n  imageAlt?: string;\n  template?: boolean;\n  family?: string;\n  difficulty?: 'basic' | 'applied' | 'advanced';\n}\n\nexport type QuizModeId =\n  | 'mixed'\n  | 'l1-l2'\n  | 'l3'\n  | 'l4'\n  | 'l5-l7'\n  | 'tcpip'\n  | 'troubleshooting'\n  | 'visual-l1';\n\nexport interface QuizMode {\n  id: QuizModeId;\n  title: string;\n  subtitle: string;\n  description: string;\n  icon: string;\n  groupFilter?: string;\n  count: number;\n}\n\nexport interface QuizSession {\n  questions: Question[];\n  currentIndex: number;\n  userAnswers: Record<string, number[]>;\n  submittedQuestions: Record<string, boolean>;\n  startTime: number;\n  endTime?: number;\n  isCompleted: boolean;\n  mode: QuizModeId;\n  feedbackMode: 'instant' | 'exam';\n}\n\nexport interface QuizStats {\n  totalAttempts: number;\n  highestScore: number;\n  passedCount: number;\n  history: Array<{\n    date: string;\n    mode: string;\n    score: number;\n    total: number;\n    percentage: number;\n  }>;\n}\n";
